CREATE OR REPLACE VIEW v_datalab_food_top20 AS SELECT * FROM datalab_food_rankings WHERE area_rank <= 20;
SELECT audience,COUNT(*) AS row_count FROM datalab_food_rankings GROUP BY audience;
SELECT audience,COUNT(*) AS top20_count FROM v_datalab_food_top20 GROUP BY audience;
